// Verify disjoint row ownership and the weighted-work imbalance bound.
#include "cpu_batched_verify.hpp"
#include <cstdio>
#include <numeric>
using namespace strata::m31;
int main(){size_t checks=0,covered=0;std::vector<std::vector<size_t>> patterns{{1},{8},{1,8},{8,1},{1,2,7,1,5,3},{8,8,8,8},std::vector<size_t>(32,1)};auto a=std::vector<size_t>(25,1);a[0]=8;patterns.push_back(a);std::reverse(a.begin(),a.end());patterns.push_back(a);patterns.push_back({1,4,1,2,8,4,6,6});for(auto & counts:patterns)for(size_t rows:{1,2,3,31,256,3072,6144})for(int nth:{1,2,3,7,8,31,48,64,80,96}){const size_t total=std::accumulate(counts.begin(),counts.end(),size_t(0));std::vector<size_t> work(size_t(nth),0);size_t prefix=0;for(size_t count:counts){std::vector<unsigned> owners(rows,0);for(int ith=0;ith<nth;++ith){auto [first,last]=cpu_verify_detail::weighted_rows(total,prefix,count,rows,ith,nth);if(first>last||last>rows)return 1;for(size_t row=first;row<last;++row)++owners[row];work[size_t(ith)]+=(last-first)*count;}for(unsigned n:owners)if(n!=1)return 2;prefix+=count;covered+=rows;}const auto [low,high]=std::minmax_element(work.begin(),work.end());const size_t max_count=*std::max_element(counts.begin(),counts.end());if(*high-*low>2*max_count+1)return 3;if(std::accumulate(work.begin(),work.end(),size_t(0))!=total*rows)return 4;++checks;}std::printf("{\"pass\":true,\"cases\":%zu,\"rows_covered\":%zu,\"property\":\"exactly one owner per row; total weighted work conserved; max-min work <= 2*max_multiplicity+1\"}\n",checks,covered);}
